import {CARE_GENE_FIELDS} from './care-settings.js';
import {PHYSIOLOGY_FIELDS,BODY_GENE_FIELDS} from './physiology-settings.js';
const genes={
 gmax:'Предел построения тканей за Т при достаточном запасе энергии. Вместе с окном развития и долей рождения определяет плановую массу. Также задаёт предел скорости катаболизма.',
 tAdult:'До конца этого окна можно увеличивать рекордную массу до генетического плана. Позже можно восстановить только уже достигнутую массу. Срок округляется вверх до подшага.',
 kBirth:'Плановая масса новорождённого как доля плановой взрослой массы. При недоплате вынашивания ребёнок меньше этого плана.',
 alpha:'Доля окна развития, после которой разрешается зачатие. Не является энергетическим порогом.',
 tPreg:'Срок вынашивания родителем. Фиксируется при зачатии. Недостающие платежи не переносят конец срока.',
 tau:'Срок, после которого пищевая группа выводится. Усвоенная пища тоже занимает объём до выведения. Позднее поступление в ту же группу имеет немного меньший срок.',
 Fg:'Мощность усвоения травы. Предел энергии за подшаг равен мощности × ёмкость желудка × энергия порции; мощность распределяется по возрастным группам пропорционально оставшейся энергии травы.',
 Ff:'Мощность усвоения плодов, аналогично траве. Рост суммарной мощности увеличивает постоянную стоимость содержания пищеварения.',
 Fm:'Мощность усвоения мяса. В желудке мясо усваивается и выводится по общим правилам, без внешней случайной порчи.',
};
export const PHYSIOLOGY_HELP={
 'metric-energy':['Энергия','Свободный запас тела. Максимум пропорционален текущей массе. Дефицит обязательных расходов сначала покрывается доступными тканями, затем повреждает здоровье.'],
 'metric-health':['Здоровье','Максимум пропорционален текущей массе. Удары и непокрытый дефицит уменьшают здоровье; лечение требует энергии. При нуле житель погибает.'],
 'metric-stomach':['Желудок','Занятый объём / ёмкость в порциях. Ёмкость зависит от органов и рекордной массы. Полностью усвоенная группа занимает место до срока выведения.'],
 'metric-inventory':['Инвентарь','Суммарный запас травы, плодов и мяса в порциях. Общая вместимость задана правилами мира; она не увеличивается с размером тела. Переносимое мясо портится.'],
 'reproduction-status':['Зачатие и вынашивание','Нужны возраст допуска, отсутствие текущей беременности и свободный лимит. Энергетического порога начала нет. Платежи определяют долю развития; после фиксированного срока идут непрерываемые роды.'],
 'reproduction-summary':['Выбор зачатия','Допуск и выбор относятся к зачатию, число детей — к последующим живым рождениям. Между ними проходят вынашивание и роды.'],
 'experiment-reproduction':['Развитие и размножение','Параметры gmax, tAdult, kBirth, alpha и tPreg наследуются. Пороги энергии, здоровья и интервал после рождения относятся только к прежней модели.'],
};
for(const [group,fields]of [['physiology',PHYSIOLOGY_FIELDS],['bodyGenes',BODY_GENE_FIELDS]])for(const [key,f]of Object.entries(fields))PHYSIOLOGY_HELP[group+'.'+key]=[f.label,(group==='bodyGenes'?genes[key]+' Наследуемое значение основателей; меняется поведенческой мутацией.':'Общее правило этого мира, не наследуемый ген. Изменение в форме применяется при новом запуске. Точная зависимость приведена в «О проекте → Энергия», «Пища» и «Рождение».')+' Единица: '+f.unit+'.'];

PHYSIOLOGY_HELP['physiology.portionPerAction']=[PHYSIOLOGY_FIELDS.portionPerAction.label,'Ограничивает только сбор и выкладывание. При еде переносится весь доступный объём выбранного вида пищи, который помещается в желудок; несъеденный остаток остаётся в инвентаре.'];
PHYSIOLOGY_HELP['physiology.eatSteps']=[PHYSIOLOGY_FIELDS.eatSteps.label,'Фиксированное время одного приёма пищи в подшагах, независимо от съеденного объёма. Один подшаг — 0,1 Т.'];

PHYSIOLOGY_HELP['bodyGenes.tCarry']=[CARE_GENE_FIELDS.tCarry.label,'Отдельный наследуемый срок, на который родитель берёт родившегося ребёнка. На старте половина окна развития, далее мутирует независимо в группе поведенческих свойств. Срок фиксируется при рождении. Ношение запрещает новое зачатие. Ребёнок наблюдает и ведёт память; при гибели родителя досрочно становится самостоятельным.'];
PHYSIOLOGY_HELP['physiology.feedSteps']=['Длительность кормления','Отдельное решение родителя длительностью один подшаг. Переносится выбранная пища из его запаса в свободное место желудка ребёнка; несъеденное остаётся в запасе.'];
PHYSIOLOGY_HELP['physiology.feedRate']=['Цена кормления','Двигательный расход энергии за Т при опорной массе родителя. За попытку оплачивается один подшаг, даже если желудок ребёнка полон. Энергия пищи поступает ребёнку позже через его собственное пищеварение.'];
